import math
import struct
from typing import TypeAlias

"""Note: This code was almost entirely generated by Claude code"""

"""Pack and unpack a vertex normal and tangent frame into 32 bits.

Bit layout:
    0-9    normal X, octahedral, round(x * 511) + 512
    10-19  normal Y, octahedral, round(y * 511) + 512
    20-27  tangent angle value, round(min(|sin|, |cos|) * sqrt(2) * 255)
    28     sin sign (1 = positive)
    29     cos sign (1 = positive)
    30     which of sin/cos was stored (1 = sin, 0 = cos)
    31     bitangent handedness (1 = +1, 0 = -1)
"""

Vec2: TypeAlias = tuple[float, float]
Vec3: TypeAlias = tuple[float, float, float]
Vec4: TypeAlias = tuple[float, float, float, float]

_SQRT2 = math.sqrt(2.0)


def _sgn(v: float) -> float:
    return 1.0 if v >= 0.0 else -1.0


def _dot(a: Vec3, b: Vec3) -> float:
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def _cross(a: Vec3, b: Vec3) -> Vec3:
    return (
        a[1] * b[2] - a[2] * b[1],
        a[2] * b[0] - a[0] * b[2],
        a[0] * b[1] - a[1] * b[0],
    )


def _normalize(a: Vec3) -> Vec3:
    length = math.sqrt(_dot(a, a))
    return (a[0] / length, a[1] / length, a[2] / length)


def _clamp(v: int, lo: int, hi: int) -> int:
    return max(lo, min(hi, v))


# ---- octahedral normal ----------------------------------------------------


def oct_encode(n: Vec3) -> Vec2:
    """Project a unit vector onto the octahedron and fold it into [-1, 1]^2."""
    x, y, z = n
    s = abs(x) + abs(y) + abs(z)
    x, y = x / s, y / s
    if z < 0.0:
        x, y = (1.0 - abs(y)) * _sgn(x), (1.0 - abs(x)) * _sgn(y)
    return x, y


def oct_decode(x: float, y: float) -> Vec3:
    """Inverse of `oct_encode`; returns a unit vector."""
    z = 1.0 - abs(x) - abs(y)
    if z < 0.0:
        x, y = (1.0 - abs(y)) * _sgn(x), (1.0 - abs(x)) * _sgn(y)
    return _normalize((x, y, z))


# ---- tangent frame --------------------------------------------------------


def tangent_frame(n: Vec3) -> tuple[Vec3, Vec3]:
    """Return the two unit vectors (a, b) spanning the plane perpendicular to n.

    The reference axis is +Y when |n.y| < |n.z|, otherwise -Z.
    """
    ref: Vec3 = (0.0, 1.0, 0.0) if abs(n[1]) < abs(n[2]) else (0.0, 0.0, -1.0)
    a = _normalize(_cross(ref, n))
    b = _cross(a, n)
    return a, b


# ---- unpack / pack --------------------------------------------------------


def unpack(packed: int) -> tuple[Vec3, Vec3, int]:
    """Decode a 32-bit value into (normal, tangent, handedness of +1 or -1)."""
    xi = packed & 0x3FF
    yi = (packed >> 10) & 0x3FF
    tq = (packed >> 20) & 0xFF
    sin_positive = (packed >> 28) & 1
    cos_positive = (packed >> 29) & 1
    stored_sin = (packed >> 30) & 1
    handed = (packed >> 31) & 1

    n = oct_decode((xi - 512) / 511.0, (yi - 512) / 511.0)

    small = tq / (_SQRT2 * 255.0)  # the smaller of |sin| and |cos|
    large = math.sqrt(max(0.0, 1.0 - small * small))
    sin_v, cos_v = (small, large) if stored_sin else (large, small)
    sin_v = sin_v if sin_positive else -sin_v
    cos_v = cos_v if cos_positive else -cos_v

    a, b = tangent_frame(n)
    t = _normalize(
        (
            cos_v * a[0] + sin_v * b[0],
            cos_v * a[1] + sin_v * b[1],
            cos_v * a[2] + sin_v * b[2],
        )
    )
    return n, t, (1 if handed else -1)


def pack(normal: Vec3, tangent: Vec4) -> bytes:
    """Encode a normal, tangent ( bitangent handedness (+1 or -1) in w component) into 32 bits."""
    n = _normalize(normal)
    t = tangent[0: 3]
    handedness = tangent[3]
    ox, oy = oct_encode(n)
    xi = _clamp(round(ox * 511.0) + 512, 0, 1023)
    yi = _clamp(round(oy * 511.0) + 512, 0, 1023)

    # The frame must come from the quantized normal so it matches `unpack`.
    nq = oct_decode((xi - 512) / 511.0, (yi - 512) / 511.0)
    a, b = tangent_frame(nq)
    cos_v, sin_v = _dot(t, a), _dot(t, b)
    norm = math.hypot(cos_v, sin_v)
    cos_v, sin_v = cos_v / norm, sin_v / norm

    stored_sin = abs(sin_v) < abs(cos_v)
    small = abs(sin_v) if stored_sin else abs(cos_v)
    tq = _clamp(round(small * _SQRT2 * 255.0), 0, 255)

    return struct.pack("<L",
        xi
        | (yi << 10)
        | (tq << 20)
        | (int(sin_v >= 0.0) << 28)
        | (int(cos_v >= 0.0) << 29)
        | (int(stored_sin) << 30)
        | (int(handedness > 0) << 31)
    )
